<script>
  import { onMount } from 'svelte';
  let bank = [], loading = true, loadError = '';
  let subject = 'all', topic = 'all', level = 'all', amount = '10';
  let pool = [], index = 0, selected = null, score = 0, screen = 'home';
  let answered = 0, correctTotal = 0, wrongIds = [], bookmarks = [], theme = 'light';
  $: filtered = bank.filter(q => (subject === 'all' || q.subject === subject) && (topic === 'all' || q.topic === topic) && (level === 'all' || (q.level || '基礎') === level));
  $: topics = [...new Set(bank.filter(q => subject === 'all' || q.subject === subject).map(q => q.topic))].sort((a,b) => a.localeCompare(b,'ja'));
  $: scienceCount = bank.filter(q => q.subject === 'science').length;
  $: socialCount = bank.filter(q => q.subject === 'social').length;
  $: q = pool[index];
  onMount(async () => {
    try {
      const response = await fetch('/data/questions.json');
      if (!response.ok) throw new Error('問題データを読み込めませんでした');
      const payload = await response.json(); bank = payload.questions || [];
      const saved = JSON.parse(localStorage.getItem('manabixx-study-v1') || '{}');
      answered = saved.answered || 0; correctTotal = saved.correct || 0;
      wrongIds = saved.wrong || []; bookmarks = saved.bookmarks || [];
      theme = localStorage.getItem('manabixx-theme') || 'light';
      document.documentElement.dataset.theme = theme;
    } catch (e) { loadError = e.message || '読み込みに失敗しました'; }
    finally { loading = false; }
  });
  function persist() { localStorage.setItem('manabixx-study-v1', JSON.stringify({answered,correct:correctTotal,wrong:wrongIds,bookmarks})); }
  function begin(mode='normal') {
    let list = [...filtered];
    if(mode==='wrong') list=list.filter(x=>wrongIds.includes(x.id));
    if(mode==='bookmarks') list=list.filter(x=>bookmarks.includes(x.id));
    for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}
    if(amount!=='all'&&mode==='normal') list=list.slice(0,Number(amount));
    if(!list.length){alert('この条件に合う問題がありません。');return;}
    pool=list;index=0;selected=null;score=0;screen='quiz';
  }
  function choose(i) {
    if(selected!==null)return;
    selected=i;const item=pool[index];const ok=i===item.correct;answered++;
    if(ok){score++;correctTotal++;wrongIds=wrongIds.filter(id=>id!==item.id);}
    else if(!wrongIds.includes(item.id))wrongIds=[...wrongIds,item.id];
    persist();
  }
  function next(){if(index===pool.length-1){screen='result';return;}index++;selected=null;}
  function toggleBookmark(){const id=pool[index].id;bookmarks=bookmarks.includes(id)?bookmarks.filter(x=>x!==id):[...bookmarks,id];persist();}
  function toggleTheme(){theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;localStorage.setItem('manabixx-theme',theme);}
</script>
<svelte:head>
  <title>Study — 今日の1問から、基礎を自分のものに。</title>
  <meta name="description" content="理科・社会を中心に、基礎問題を分野別に演習できる無料の学習サイト。"/>
  <link rel="manifest" href="/manifest.webmanifest"/><link rel="icon" href="/assets/study-icon.svg" type="image/svg+xml"/>
  <link rel="preconnect" href="https://fonts.googleapis.com"/><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="anonymous"/>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Noto+Sans+JP:wght@400;500;600;700;800&display=swap" rel="stylesheet"/>
</svelte:head>
<div class="shell">
  <header><a class="brand" href="/"><span class="mark">S</span>study<span class="dot">.</span></a><nav><a class:active={screen==='home'} href="/">学習する</a><a href="/legacy/summary.html">要点まとめ</a><a href="/legacy/public-exam.html">公立入試問題</a><a href="/legacy/release-notes.html">更新履歴</a></nav><button class="theme" onclick={toggleTheme} aria-label="テーマ切替">{theme==='light'?'☾':'☀'}</button></header>
  {#if screen==='home'}
    <main>
      <section class="hero"><div><span class="eyebrow">YOUR DAILY STUDY SPACE</span><h1>今日の1問から、<br/><em>基礎を自分のものに。</em></h1><p>小さく解いて、少しずつ積み上げる。毎日の学習を、ここから。</p><button class="primary" onclick={()=>document.getElementById('practice')?.scrollIntoView({behavior:'smooth'})}>演習を始める　→</button></div><div class="hero-art" aria-hidden="true"><div class="sheet"><b>✳</b><i></i><i></i><i></i><strong>✓</strong></div></div></section>
      <section id="practice" class="practice"><div class="heading"><div><span class="eyebrow">FOUNDATION PRACTICE</span><h2>基礎網羅問題</h2><p>理科・社会を中心に、分野別・難易度別でくり返し演習。</p></div><div class="total"><b>{bank.length.toLocaleString('ja-JP')}</b><small>問収録</small></div></div>
      <div class="stats"><div><span>⚗</span><label>理科</label><b>{scienceCount.toLocaleString('ja-JP')}<small>問</small></b></div><div><span>⌖</span><label>社会</label><b>{socialCount.toLocaleString('ja-JP')}<small>問</small></b></div><div><span>▤</span><label>累計回答</label><b>{answered.toLocaleString('ja-JP')}<small>問</small></b></div></div>
      {#if loading}<div class="panel status">問題データを読み込んでいます…</div>{:else if loadError}<div class="panel status error">{loadError}</div>{:else}
      <div class="panel"><div class="panel-heading"><div><span class="eyebrow">MAKE IT YOURS</span><h3>演習内容を選ぶ</h3></div><small>{filtered.length.toLocaleString('ja-JP')}問から選択</small></div>
      <div class="segmented"><button class:chosen={subject==='all'} onclick={()=>{subject='all';topic='all';}}>理科・社会</button><button class:chosen={subject==='science'} onclick={()=>{subject='science';topic='all';}}>理科</button><button class:chosen={subject==='social'} onclick={()=>{subject='social';topic='all';}}>社会</button></div>
      <div class="filters"><label>分野<select bind:value={topic}><option value="all">すべての分野</option>{#each topics as t}<option value={t}>{t}</option>{/each}</select></label><label>難易度<select bind:value={level}><option value="all">すべて</option><option value="基礎">基礎</option><option value="標準">標準</option><option value="応用">応用</option></select></label><label>問題数<select bind:value={amount}><option value="10">10問</option><option value="20">20問</option><option value="30">30問</option><option value="50">50問</option><option value="all">全問</option></select></label></div>
      <button class="primary start" onclick={()=>begin()}>この条件で演習を始める　→</button></div>
      <div class="quick"><button onclick={()=>begin('wrong')}><b>↻</b><span><strong>苦手問題を復習</strong><small>{wrongIds.length}問・間違えた問題</small></span><i>→</i></button><button onclick={()=>begin('bookmarks')}><b>☆</b><span><strong>保存した問題</strong><small>{bookmarks.length}問・あとで解き直す</small></span><i>→</i></button></div>
      {/if}</section>
      <section class="note"><div><span class="eyebrow">KEEP GOING</span><h2>続けることが、いちばんの近道。</h2><p>昨日よりひとつ分かることを増やしていこう。</p></div><a href="/legacy/motivation.html">学習のヒントを見る ↗</a></section>
    </main>
  {:else if screen==='quiz'}
    <main class="quiz"><div class="quizbar"><button onclick={()=>screen='home'}>← 問題一覧へ</button><span>{index+1} / {pool.length}</span></div><div class="progress"><i style="width:{index/pool.length*100}%"></i></div>
    <div class="tags"><span>{q.subject==='science'?'理科':'社会'}</span><span>{q.topic}</span><span>{q.level||'基礎'}</span></div>
    <section class="question"><small>QUESTION　<b>{String(index+1).padStart(2,'0')}</b></small><h1>{q.prompt}</h1><div class="answers">{#each q.options as option,i}<button class:correct={selected!==null&&i===q.correct} class:incorrect={selected===i&&selected!==q.correct} class:dim={selected!==null&&i!==selected&&i!==q.correct} disabled={selected!==null} onclick={()=>choose(i)}><span>{['A','B','C','D'][i]}</span>{option}</button>{/each}</div>
    {#if selected!==null}<div class:good={selected===q.correct} class:bad={selected!==q.correct} class="explanation"><b>{selected===q.correct?'正解！':'不正解'}</b><p>{q.explanation}</p>{#if q.sourceNote}<small>{q.sourceNote}{q.sourceRef ? ' 出典形式：'+q.sourceRef : ''}</small>{/if}</div>{/if}
    <div class="actions"><button class="save" onclick={toggleBookmark}>{bookmarks.includes(q.id)?'★ 保存済み':'☆ あとで復習'}</button><button class="primary" disabled={selected===null} onclick={next}>{index===pool.length-1?'結果を見る':'次の問題へ'}　→</button></div></section></main>
  {:else}
    <main class="result"><span class="eyebrow">SESSION COMPLETE</span><h1>おつかれさま！</h1><p>今日の積み重ねを、次の一歩につなげよう。</p><section class="result-card"><strong>{score}<small> / {pool.length}</small></strong><span>正解数</span><div class="result-track"><i style="width:{score/pool.length*100}%"></i></div><b>正答率 {Math.round(score/pool.length*100)}%</b></section><button class="primary" onclick={()=>begin()}>もう一度演習する →</button> <button class="save" onclick={()=>screen='home'}>ホームに戻る</button></main>
  {/if}
  <footer><span class="brand"><span class="mark">S</span>study<span class="dot">.</span></span><small>MANABIXX · Learn at your own pace.</small></footer>
</div>
<style>
:global(*){box-sizing:border-box}:global(:root){font-family:'DM Sans','Noto Sans JP',sans-serif;color:#242837;background:#f5f6f8;--bg:#f5f6f8;--surface:#fff;--ink:#242837;--muted:#858b99;--line:#e8eaf0;--accent:#655ce2;--soft:#eeedff}:global(:root[data-theme='dark']){color-scheme:dark;--bg:#11131a;--surface:#1b1e28;--ink:#f0f1f7;--muted:#a0a6b5;--line:#303441;--accent:#9189ff;--soft:#2b2947}:global(body){margin:0;background:var(--bg);color:var(--ink)}button,a,select{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}.shell{max-width:1160px;margin:auto;padding:0 36px}header{height:78px;display:flex;align-items:center;border-bottom:1px solid var(--line);gap:45px}.brand{display:flex;align-items:center;font-size:21px;font-weight:800;letter-spacing:-1px}.mark{width:31px;height:31px;border-radius:10px;background:var(--accent);color:white;display:grid;place-items:center;margin-right:9px}.dot{color:var(--accent)}nav{display:flex;gap:27px;margin:auto;color:var(--muted);font-size:12px}nav .active{color:var(--ink);font-weight:700}.theme{width:38px;height:38px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink)}.hero{margin:42px 0 62px;min-height:290px;border-radius:25px;background:var(--soft);padding:43px 60px;display:flex;align-items:center;justify-content:space-between;overflow:hidden}.eyebrow{font-size:10px;letter-spacing:1.6px;font-weight:800;color:var(--accent)}.hero h1{font-size:37px;line-height:1.5;letter-spacing:-1.6px;margin:14px 0 8px}.hero h1 em{font-style:normal;color:var(--accent)}.hero p,.heading p,.note p{font-size:12px;color:var(--muted)}.primary{border:0;background:var(--accent);color:white;border-radius:11px;padding:14px 19px;font-size:12px;font-weight:700}.primary:disabled{opacity:.4}.hero-art{width:220px;height:190px;display:grid;place-items:center;position:relative}.hero-art:before,.hero-art:after{content:'';position:absolute;width:230px;height:125px;border:1px solid #c4c0f2;border-radius:50%;transform:rotate(-22deg)}.hero-art:after{transform:rotate(45deg);width:180px;height:190px}.sheet{z-index:1;width:130px;height:150px;border-radius:17px;background:white;box-shadow:0 17px 35px #514ba52b;padding:20px;position:relative}.sheet b{font-size:27px;color:#8179eb}.sheet i{display:block;height:6px;background:#eeedfa;border-radius:6px;margin-top:10px}.sheet i:nth-of-type(2){width:75%}.sheet i:nth-of-type(3){width:55%}.sheet strong{position:absolute;right:-10px;bottom:13px;width:35px;height:35px;border-radius:11px;background:var(--accent);color:white;display:grid;place-items:center}.practice{margin-bottom:55px}.heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.heading h2{font-size:23px;margin:6px 0}.total{text-align:right}.total b{display:block;font-size:25px}.total small{font-size:10px;color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:15px}.stats>div{background:var(--surface);border:1px solid var(--line);border-radius:15px;padding:15px 18px;display:flex;align-items:center;gap:10px;font-size:12px;color:var(--muted)}.stats span{font-size:19px;color:var(--accent)}.stats b{margin-left:auto;color:var(--ink);font-size:18px}.stats small{font-size:10px;margin-left:3px;color:var(--muted)}.panel,.status{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 12px 38px #26304a0b}.status{text-align:center;color:var(--muted)}.error{color:#c55}.panel-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:17px}.panel-heading h3{margin:5px 0;font-size:18px}.panel-heading small{font-size:10px;color:var(--muted)}.segmented{display:flex;gap:5px;background:var(--bg);padding:5px;border-radius:11px;width:max-content;margin-bottom:17px}.segmented button{border:0;background:transparent;color:var(--muted);padding:9px 17px;border-radius:8px;font-size:11px}.segmented button.chosen{background:var(--surface);color:var(--ink);font-weight:700}.filters{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.filters label{display:grid;gap:7px;font-size:10px;color:var(--muted)}select{padding:11px;border:1px solid var(--line);border-radius:9px;background:var(--bg);color:var(--ink);width:100%;font-size:12px}.start{width:100%;margin-top:19px}.quick{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.quick button{display:flex;align-items:center;gap:12px;text-align:left;padding:15px;background:var(--surface);border:1px solid var(--line);border-radius:14px;color:var(--ink)}.quick button>b{font-size:20px;color:var(--accent)}.quick strong,.quick small{display:block}.quick strong{font-size:12px}.quick small{font-size:10px;color:var(--muted);margin-top:4px}.quick i{margin-left:auto;color:var(--muted);font-style:normal}.note{display:flex;align-items:center;justify-content:space-between;padding:23px 25px;border:1px solid var(--line);background:var(--surface);border-radius:18px;margin-bottom:45px}.note h2{font-size:17px;margin:6px 0}.note p{margin:0}.note>a{font-size:11px;color:var(--accent);font-weight:700}footer{height:70px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:var(--muted)}footer small{font-size:10px}.quiz{max-width:760px;margin:35px auto 65px}.quizbar{display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.quizbar button{border:0;background:none;color:var(--muted)}.progress,.result-track{height:5px;background:var(--line);border-radius:5px;margin:16px 0 25px;overflow:hidden}.progress i,.result-track i{height:100%;display:block;background:var(--accent)}.tags{display:flex;gap:7px}.tags span{padding:6px 10px;border:1px solid var(--line);border-radius:20px;color:var(--muted);font-size:10px}.question{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:28px;margin-top:13px}.question>small{font-size:10px;letter-spacing:1px;color:var(--muted)}.question>small b{color:var(--accent)}.question h1{font-size:22px;line-height:1.8;margin:18px 0 23px}.answers{display:grid;gap:9px}.answers button{display:flex;align-items:center;gap:13px;text-align:left;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--bg);color:var(--ink);font-size:13px}.answers button span{width:26px;height:26px;border-radius:8px;background:var(--surface);display:grid;place-items:center;font-size:10px;color:var(--muted);flex:none}.answers button.correct{background:#e9f7f1;border-color:#43a783;color:#236b55}.answers button.incorrect{background:#fff0f1;border-color:#df7880;color:#a13e48}.answers button.dim{opacity:.45}.explanation{padding:16px;margin-top:17px;border-radius:12px;background:var(--bg);font-size:12px;line-height:1.8}.explanation.good>b{color:#278768}.explanation.bad>b{color:#d05b66}.explanation p{margin:6px 0}.explanation small{color:var(--muted)}.actions{display:flex;justify-content:space-between;align-items:center;margin-top:20px}.save{border:1px solid var(--line);border-radius:10px;padding:12px 14px;background:var(--surface);color:var(--muted);font-size:11px}.result{text-align:center;max-width:560px;margin:70px auto}.result h1{font-size:32px}.result p{font-size:12px;color:var(--muted)}.result-card{margin:28px 0;padding:28px;border:1px solid var(--line);background:var(--surface);border-radius:18px}.result-card>strong{display:block;font-size:48px;color:var(--accent)}.result-card>strong small{font-size:16px;color:var(--muted)}.result-card>span,.result-card>b{font-size:11px;color:var(--muted)}.result-track{margin:18px 0}.result .save{margin-left:7px}@media(max-width:760px){.shell{padding:0 17px}header{height:65px;gap:10px}.brand{font-size:17px}nav{gap:12px;font-size:10px}nav a:nth-child(3){display:none}.theme{width:34px;height:34px}.hero{margin:24px 0 40px;padding:28px 23px;min-height:225px}.hero h1{font-size:26px}.hero p{max-width:260px;line-height:1.8}.hero-art{width:115px;transform:scale(.7);margin-right:-38px}.heading h2{font-size:20px}.heading p{max-widt